// === Tab: mySketch ===
let NUM=320;
let A = new Array(NUM);
let RANGE=50;
let COMPRESS = 0.985;
let WEIGHT = 8;

class Attract {
  x, y;

  constructor() {
    x=random(-width/2, width/2);
    y=random(-height/2, height/2);
  }

  function update() {
    point(x, y);

    let vx=0;
    let vy=0;
    for (let a of A) {
      vx+=(dist(x-RANGE, y, a.x, a.y)<RANGE)? -1 : (dist(x+RANGE, y, a.x, a.y)<RANGE) ? 1:0; 
      vy+=(dist(x, y-RANGE, a.x, a.y)<RANGE)? -1 : (dist(x, y+RANGE, a.x, a.y)<RANGE) ? 1:0;
    }

    let f = sin(radians(frameCount));
    x+=vx*f;
    y+=vy*f;
    x*=COMPRESS;
    y*=COMPRESS;
  }
}

function setup() {
  createCanvas(640, 640);
  for (i=0; i<NUM; i++) {
    A[i]=new Attract();
  }
  stroke(255);
  strokeWeight(WEIGHT);
}

function draw() {
  background(0);
  translate(width/2, height/2);  
  for (let a of A) {
    a.update();
  }
}

